// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum) public {
        vm.assume(blockNum >= 1 && blockNum <= type(uint64).max);
        vm.roll(blockNum);
        vm.warp(1);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback failed");

        bool balanceZeroAfterCall = address(c).balance == 0;
        bool blockIsMultipleOf15 = (blockNum % 15 == 0);
        assertTrue(balanceZeroAfterCall == blockIsMultipleOf15);
    }
}
